package com.dat.ai_receptionist_web.service.Catalog;
import com.dat.ai_receptionist_web.domain.Catalog.*; import com.dat.ai_receptionist_web.dto.*; import com.dat.ai_receptionist_web.dto.Catalog.*; import com.dat.ai_receptionist_web.error.*; import com.dat.ai_receptionist_web.error.code.CatalogErrorCode; import com.dat.ai_receptionist_web.mapper.Catalog.TrainingPlanAccessRuleMapper; import com.dat.ai_receptionist_web.repository.Catalog.*; import lombok.RequiredArgsConstructor; import org.springframework.data.domain.Pageable; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service @RequiredArgsConstructor public class TrainingPlanAccessRuleService {
 private final TrainingPlanAccessRuleRepository repository; private final TrainingPlanService plans; private final CourseRepository courses; private final TrainingPlanAccessRuleMapper mapper;
 @Transactional(readOnly=true) public PageResponse<TrainingPlanAccessRuleDTO.SimpleResponse> list(UUID planId,Pageable pageable){return PageResponse.of(repository.findAllDetailed(planId,pageable),mapper::toSimpleResponse);} @Transactional(readOnly=true) public TrainingPlanAccessRuleDTO.Response get(UUID id){return mapper.toResponse(find(id));}
 @Transactional public TrainingPlanAccessRuleDTO.Response create(TrainingPlanAccessRuleDTO.CreateRequest r){var e=new TrainingPlanAccessRule();e.setTrainingPlan(plans.find(r.trainingPlanId()));e.setTargetCourse(course(r.targetCourseId()));mapper.updateEntity(r,e);return mapper.toResponse(repository.save(e));}
 @Transactional public TrainingPlanAccessRuleDTO.Response update(UUID id,TrainingPlanAccessRuleDTO.UpdateRequest r){var e=find(id);e.setTargetCourse(course(r.targetCourseId()));mapper.updateEntity(r,e);return mapper.toResponse(e);} @Transactional public void delete(UUID id){repository.delete(find(id));}
 private TrainingPlanAccessRule find(UUID id){return repository.findDetailedById(id).orElseThrow(()->new ApiException(CatalogErrorCode.TRAINING_PLAN_ACCESS_RULE_NOT_FOUND));} private Course course(UUID id){return courses.findById(id).orElseThrow(()->new ApiException(CatalogErrorCode.COURSE_NOT_FOUND));}
}
